1	//! Streaming export writer (fixes #208 export OOM).
2	//!
3	//! Replaces the previous "load the entire dataset into a `Vec<u8>` buffer,
4	//! then write it to disk" pattern with cursor-paginated streaming inside
5	//! a `REPEATABLE READ READ ONLY` Postgres transaction. Records are
6	//! fetched in bounded pages, each page is serialized into a small
7	//! per-page buffer, and each per-page buffer is streamed to disk before
8	//! the next page is fetched.
9	//!
10	//! Snapshot-stable: pagination runs inside a single snapshot
11	//! transaction, and the dataset `ORDER BY` carries a `dt.id DESC`
12	//! tiebreaker so concurrent ingestion cannot cause page boundaries to
13	//! skip or duplicate rows (addresses PR #238 [P1] pagination concern).
14	//!
15	//! Cancellable: the caller supplies a [`CancellationToken`] that the
16	//! worker drives from the heartbeat task — when the export job's lease
17	//! is reclaimed by another worker, the token is cancelled, and this
18	//! function aborts cleanly without emitting more bytes. The caller is
19	//! responsible for cleaning up any attempt-scoped temp artifact before
20	//! publishing to the final download path.
21	//!
22	//! Peak per-job memory is bounded by `PAGE_SIZE * per-record bytes`
23	//! regardless of total dataset size, so a single large export can no
24	//! longer OOM-kill the worker process and take down co-located workers.
25	//!
26	//! File opens use `O_NOFOLLOW` in the same way as
27	//! [`crate::write_no_follow`] (defense-in-depth for #220 TOCTOU symlink
28	//! attacks) but the file handle is kept open across the paged write
29	//! loop rather than opened/closed per page.
30	
31	use crate::export_csv::{
32	    balance_history_csv_header, decoded_events_csv_header, hl_fills_csv_header,
33	    hl_funding_csv_header, hl_pnl_summary_csv_header, hl_positions_csv_header,
34	    hl_trade_history_csv_header, native_balance_deltas_csv_header, pool_snapshots_csv_header,
35	    protocol_events_csv_header, token_transfers_csv_header, wallet_ledger_csv_header,
36	    write_balance_history_csv_rows, write_decoded_events_csv_rows, write_hl_fills_csv_rows,
37	    write_hl_funding_csv_rows, write_hl_pnl_summary_csv_rows, write_hl_positions_csv_rows,
38	    write_hl_trade_history_csv_rows, write_native_balance_deltas_csv_rows,
39	    write_pool_snapshots_csv_rows, write_protocol_events_csv_rows, write_token_transfers_csv_rows,
40	    write_wallet_ledger_csv_rows,
41	};
42	use crate::ExportMetadata;
43	use serde::Serialize;
44	use spectraplex_adapters::repo::Repository;
45	use spectraplex_adapters::v2_repo::ExportRecordBatch;
46	use spectraplex_core::materializer::ExportFormat;
47	use tokio::fs::File;
48	use tokio::io::{AsyncWriteExt, BufWriter};
49	use tokio_util::sync::CancellationToken;
50	use tracing::info;
51	use uuid::Uuid;
52	
53	/// Records per paged query. Keeps peak per-job memory bounded to
54	/// roughly `PAGE_SIZE * sizeof(record)` regardless of total dataset size.
55	///
56	/// Chosen to match the "10,000 records per batch" suggestion from issue
57	/// #208 — large enough to amortize query round-trip cost, small enough that
58	/// a concurrent fleet of export workers cannot collectively OOM the host.
59	pub(crate) const PAGE_SIZE: i64 = 10_000;
60	
61	/// Absolute safety cap on records per export job.
62	const EXPORT_HARD_CAP: i64 = 1_000_000;
63	
64	/// BufWriter buffer capacity. Large enough that the writer does not flush
65	/// on every serialized record, small enough to stay well under the
66	/// PAGE_SIZE-bounded peak.
67	const WRITER_BUFFER_BYTES: usize = 256 * 1024;
68	
69	/// Channel depth for page handoff between the DB snapshot task and the
70	/// disk writer. Kept small so DB streaming throttles to disk speed
71	/// rather than buffering whole pages in RAM.
72	const PAGE_CHANNEL_CAPACITY: usize = 2;
73	
74	/// Open the export target file with `O_NOFOLLOW` (mirrors
75	/// [`crate::write_no_follow`]'s symlink-refusing open) and return it as an
76	/// async [`tokio::fs::File`] suitable for streaming writes.
77	async fn open_no_follow(path: &str) -> std::io::Result<File> {
78	    use std::os::unix::fs::OpenOptionsExt;
79	    let path_owned = path.to_owned();
80	    let std_file = tokio::task::spawn_blocking(move || {
81	        std::fs::OpenOptions::new()
82	            .write(true)
83	            .create(true)
84	            .truncate(true)
85	            .custom_flags(libc::O_NOFOLLOW)
86	            .open(&path_owned)
