261	/// Stream an export for `dataset` to `output_path`, fetching records
262	/// in pages of [`PAGE_SIZE`] inside a `REPEATABLE READ READ ONLY`
263	/// transaction and writing each page directly to disk.
264	///
265	/// Returns the total number of records written and the provenance
266	/// metadata gathered at the start of the export.
267	///
268	/// # Cancellation
269	///
270	/// The `cancel` token is checked before the write loop pulls each
271	/// page from the channel and before each async write. When cancelled,
272	/// the snapshot task aborts the remaining pages, the transaction is
273	/// rolled back implicitly on drop, and this function returns an error.
274	/// The caller is responsible for deleting the (attempt-scoped) output
275	/// file so a reclaiming worker never sees partial bytes.
276	#[allow(clippy::too_many_arguments)]
277	pub(crate) async fn write_export_to_file(
278	    repo: &Repository,
279	    dataset: &str,
280	    format: ExportFormat,
281	    target_id: Option<Uuid>,
282	    network: Option<&str>,
283	    time_start: Option<i64>,
284	    time_end: Option<i64>,
285	    output_path: &str,
286	    cancel: CancellationToken,
287	) -> anyhow::Result<(usize, ExportMetadata)> {
288	    let meta = fetch_export_metadata(repo, dataset, target_id, network).await;
289	
290	    // Reject unknown datasets before opening the file so we don't leave
291	    // an empty artifact behind.
292	    let csv_header =
293	        csv_header_for(dataset).ok_or_else(|| anyhow::anyhow!("Unknown dataset: {dataset}"))?;
294	
295	    let file = open_no_follow(output_path).await?;
296	    let mut writer = BufWriter::with_capacity(WRITER_BUFFER_BYTES, file);
297	
298	    // Always emit the CSV header before the page loop so an export with
299	    // zero rows still produces a header-only file (fixes PR #238 [P2]
300	    // empty-CSV regression). For JSONL, zero rows correctly produces an
301	    // empty file.
302	    if matches!(format, ExportFormat::Csv) {
303	        writer.write_all(csv_header.as_bytes()).await?;
304	    }
305	
306	    // Spawn the snapshot streamer on a separate task so the snapshot
307	    // transaction and the write loop run concurrently, with backpressure
308	    // provided by the small channel.
309	    let (page_tx, mut page_rx) =
310	        tokio::sync::mpsc::channel::<ExportRecordBatch>(PAGE_CHANNEL_CAPACITY);
311	    let repo_clone = repo.clone();
312	    let dataset_owned = dataset.to_string();
313	    let network_owned = network.map(|s| s.to_string());
314	    let cancel_for_stream = cancel.clone();
315	
316	    let stream_task = tokio::spawn(async move {
317	        repo_clone
318	            .stream_export_snapshot(
319	                &dataset_owned,
320	                target_id,
321	                network_owned.as_deref(),
322	                time_start,
323	                time_end,
324	                PAGE_SIZE,
325	                EXPORT_HARD_CAP,
326	                cancel_for_stream,
327	                page_tx,
328	            )
329	            .await
330	    });
331	
332	    let mut total: usize = 0;
333	    let write_result: anyhow::Result<()> = async {
334	        while let Some(batch) = page_rx.recv().await {
335	            if cancel.is_cancelled() {
336	                anyhow::bail!("export cancelled during write loop");
337	            }
338	
339	            let n = batch.len();
340	            let mut buf: Vec<u8> = Vec::with_capacity(n.saturating_mul(512));
341	            encode_batch(&batch, format, &mut buf)?;
342	            writer.write_all(&buf).await?;
343	            total += n;
344	        }
345	        Ok(())
346	    }
347	    .await;
348	
349	    // Always drain the snapshot task so we propagate its errors (e.g.
350	    // lease-lost cancellation, DB errors) and don't leak a pending
351	    // transaction. If the write loop failed, cancel the token so the
352	    // snapshot task short-circuits rather than continuing to push
353	    // pages into a dropped channel.
354	    if write_result.is_err() {
355	        cancel.cancel();
356	    }
357	
358	    let stream_result = stream_task
359	        .await
360	        .map_err(|e| anyhow::anyhow!("export snapshot task panicked: {e}"))?;
361	
362	    // Surface the first error we have. The write loop's error is
363	    // generally the root cause (cancellation, disk failure); the
364	    // snapshot task typically reports the secondary "channel dropped".
365	    write_result?;
366	    let streamed = stream_result?;
367	
368	    // Sanity check: the DB-reported total must match what we wrote.
369	    // A mismatch would indicate dropped pages or a bookkeeping bug.
370	    debug_assert_eq!(streamed, total);
371	
372	    writer.flush().await?;
373	
374	    info!(
375	        dataset,
376	        record_count = total,
377	        output_path,
378	        "Export streamed to disk"
379	    );
380	
381	    Ok((total, meta))
382	}
