1	//! Durable export worker loop.
2	//!
3	//! Claims pending `export_jobs` rows from Postgres, streams the export
4	//! to disk via [`crate::export_stream::write_export_to_file`], optionally
5	//! delivers to a configured sink, and marks jobs complete/failed
6	//! durably. Heartbeats while running so that dead workers are detected
7	//! and their jobs reclaimed.
8	//!
9	//! Lease safety (PR #238 [P1] fix):
10	//!
11	//! The worker writes the export artifact to an *attempt-scoped* temp
12	//! file named `{job_id}.{worker_hash}.{ext}.tmp`, and only atomically
13	//! renames it to the canonical `{job_id}.{ext}` download path after a
14	//! lease-holder-confirming `update_export_job_status(..., worker_id)`
15	//! has returned `Ok(true)`. If the heartbeat loop reports the job's
16	//! lease was reclaimed, a `lease_lost` [`CancellationToken`] is
17	//! cancelled — that token is propagated into the page loop in
18	//! `write_export_to_file`, so the stale worker short-circuits the DB
19	//! snapshot, skips the rename, and removes its temp file. The new
20	//! owner starts from a clean state and writes to a distinct temp path,
21	//! so the two workers cannot truncate each other's artifacts or hand
22	//! out partial bytes via `/download`.
23	
24	use std::sync::Arc;
25	use std::time::Duration;
26	
27	use spectraplex_adapters::repo::Repository;
28	use spectraplex_core::config::AppConfig;
29	use spectraplex_core::materializer::{DeliveryMetadata, ExportFormat, SinkConfig};
30	use spectraplex_core::v2::ExportJob;
31	use tokio::sync::Semaphore;
32	use tokio_util::sync::CancellationToken;
33	use tracing::{error, info, warn};
34	use uuid::Uuid;
35	
36	use crate::build_sink;
37	use crate::export_stream::write_export_to_file;
38	
39	/// How often the worker polls for new jobs when idle.
40	const POLL_INTERVAL: Duration = Duration::from_secs(2);
41	
42	/// How often the worker sends heartbeats while executing a job.
43	const HEARTBEAT_INTERVAL: Duration = Duration::from_secs(30);
44	
45	/// Spawn the export worker loop. Returns immediately; the worker runs
46	/// until `cancel` is triggered.
47	pub fn spawn_export_worker(
48	    repo: Repository,
49	    config: AppConfig,
50	    job_semaphore: Arc<Semaphore>,
51	    cancel: CancellationToken,
52	) {
53	    let worker_id = format!("export-worker-{}", Uuid::new_v4());
54	    info!(worker_id = %worker_id, "Starting export worker");
55	
56	    tokio::spawn(async move {
57	        loop {
58	            tokio::select! {
59	                _ = cancel.cancelled() => {
60	                    info!(worker_id = %worker_id, "Export worker shutting down");
61	                    return;
62	                }
63	                _ = worker_tick(&repo, &config, &job_semaphore, &worker_id) => {}
64	            }
65	        }
66	    });
67	}
68	
69	async fn worker_tick(
70	    repo: &Repository,
71	    config: &AppConfig,
72	    job_semaphore: &Arc<Semaphore>,
73	    worker_id: &str,
74	) {
75	    let permit = match Arc::clone(job_semaphore).try_acquire_owned() {
76	        Ok(permit) => permit,
77	        Err(_) => {
78	            tokio::time::sleep(POLL_INTERVAL).await;
79	            return;
80	        }
81	    };
82	
83	    match repo.claim_export_job(worker_id).await {
84	        Ok(Some(job)) => {
85	            info!(
86	                job_id = %job.id,
87	                dataset = %job.dataset,
88	                format = %job.format,
89	                worker_id = %worker_id,
90	                "Claimed export job"
91	            );
92	            execute_export_job(repo, config, worker_id, &job, permit).await;
93	        }
94	        Ok(None) => {
95	            drop(permit);
96	            tokio::time::sleep(POLL_INTERVAL).await;
97	        }
98	        Err(e) => {
99	            drop(permit);
100	            error!(error = %e, worker_id = %worker_id, "Failed to claim export job");
101	            tokio::time::sleep(POLL_INTERVAL).await;
102	        }
103	    }
104	}
105	
106	/// Build an attempt-scoped temp path for this worker's export. Two
107	/// workers that race on the same `job_id` get different temp paths, so
108	/// a stale worker cannot truncate the new owner's artifact.
109	fn attempt_temp_path(exports_dir: &str, job_id: Uuid, worker_id: &str, ext: &str) -> String {
110	    // Short, filesystem-safe tag derived from the worker id. FNV-style
111	    // hash is fine — collision risk is negligible at the (active worker
112	    // count) scale this operates at.
113	    use std::collections::hash_map::DefaultHasher;
114	    use std::hash::{Hash, Hasher};
115	    let mut h = DefaultHasher::new();
116	    worker_id.hash(&mut h);
117	    let tag = format!("{:016x}", h.finish());
118	    format!("{exports_dir}/{job_id}.{tag}.{ext}.tmp")
119	}
120	
121	/// Best-effort remove a file, swallowing NotFound and logging other
122	/// errors. Used by the failure paths in `execute_export_job` to clean
123	/// up attempt-scoped temp artifacts without masking the real error.
124	async fn best_effort_unlink(path: &str, job_id: Uuid) {
125	    match tokio::fs::remove_file(path).await {
126	        Ok(()) => {}
127	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
128	        Err(e) => {
129	            warn!(
130	                job_id = %job_id,
131	                error = %e,
132	                file = %path,
133	                "Failed to clean up temp export artifact",
134	            );
135	        }
136	    }
137	}
138	
139	async fn execute_export_job(
140	    repo: &Repository,
141	    config: &AppConfig,
142	    worker_id: &str,
143	    job: &ExportJob,
144	    _permit: tokio::sync::OwnedSemaphorePermit,
145	) {
146	    let job_id = job.id;
147	    let export_dir = &config.export_dir;
148	
149	    // `heartbeat_cancel` stops the heartbeat task when the export is
150	    // done. `lease_lost` is a *distinct* token that the heartbeat task
151	    // flips when `heartbeat_export_job` reports the job has been
152	    // reclaimed. Downstream code (the streaming writer and the final
153	    // rename) checks `lease_lost` to short-circuit its side effects
154	    // so a stale worker cannot publish a partial/bogus artifact over
155	    // the new owner's work.
156	    let heartbeat_cancel = CancellationToken::new();
157	    let lease_lost = CancellationToken::new();
158	    {
159	        let hb_repo = repo.clone();
160	        let hb_worker = worker_id.to_string();
161	        let hb_cancel = heartbeat_cancel.clone();
162	        let hb_lost = lease_lost.clone();
163	        let hb_job_id = job_id;
164	        tokio::spawn(async move {
165	            let mut interval = tokio::time::interval(HEARTBEAT_INTERVAL);
166	            interval.tick().await; // first tick is immediate
167	            loop {
168	                tokio::select! {
169	                    _ = hb_cancel.cancelled() => { return; }
170	                    _ = interval.tick() => {
171	                        match hb_repo.heartbeat_export_job(hb_job_id, &hb_worker).await {
172	                            Ok(true) => {}
173	                            Ok(false) => {
174	                                warn!(job_id = %hb_job_id, "Heartbeat returned false — lease lost");
175	                                // Propagate to the write loop so it stops
176	                                // before any more side effects.
177	                                hb_lost.cancel();
178	                                return;
179	                            }
180	                            Err(e) => {
181	                                warn!(job_id = %hb_job_id, error = %e, "Heartbeat failed");
182	                            }
183	                        }
184	                    }
185	                }
186	            }
187	        });
188	    }
189	
190	    let (target_id, network, time_start, time_end) = parse_filters(&job.filters);
191	
192	    let format: ExportFormat = match job.format.parse() {
193	        Ok(f) => f,
194	        Err(_) => {
195	            heartbeat_cancel.cancel();
196	            let err_msg = format!("Invalid export format: {}", job.format);
197	            error!(job_id = %job_id, error = %err_msg, "Export job failed");
198	            if let Err(e) = repo
199	                .update_export_job_status(
200	                    job_id,
201	                    "failed",
202	                    None,
203	                    None,
204	                    Some(&err_msg),
205	                    worker_id,
206	                    None,
207	                    None,
208	                    None,
209	                    None,
210	                    None,
211	                    None,
212	                )
213	                .await
214	            {
215	                error!(job_id = %job_id, error = %e, "Failed to mark job failed");
216	            }
217	            return;
218	        }
219	    };
220	
221	    let ext = match format {
222	        ExportFormat::Jsonl => "jsonl",
223	        ExportFormat::Csv => "csv",
224	    };
225	
226	    let exports_dir = format!("{}/exports", export_dir);
227	    if let Err(e) = tokio::fs::create_dir_all(&exports_dir).await {
228	        let err_msg = format!("Failed to create exports directory: {e}");
229	        error!(job_id = %job_id, error = %err_msg, "Export job failed");
230	        let _ = update_or_abort(
231	            repo,
232	            job_id,
233	            "failed",
234	            None,
235	            None,
236	            Some(&err_msg),
237	            worker_id,
238	            None,
239	            None,
240	            None,
241	            None,
242	            None,
243	            None,
244	        )
245	        .await;
246	        heartbeat_cancel.cancel();
247	        return;
248	    }
249	
250	    let temp_path = attempt_temp_path(&exports_dir, job_id, worker_id, ext);
251	    let final_path = format!("{}/{}.{}", exports_dir, job_id, ext);
252	
253	    // Stream the export into the attempt-scoped temp path. Lease-loss
254	    // cancellation propagates into the snapshot+write loop.
255	    let result = write_export_to_file(
256	        repo,
257	        &job.dataset,
258	        format,
259	        target_id,
260	        network.as_deref(),
261	        time_start,
262	        time_end,
263	        &temp_path,
264	        lease_lost.clone(),
265	    )
266	    .await;
267	
268	    // Heartbeat deliberately stays alive through publish + sink
269	    // delivery + final status update, so we don't release the lease
270	    // until side effects are durable.
271	
272	    match result {
273	        Ok((record_count, _export_meta)) => {
274	            // Before touching the canonical download path, confirm we
275	            // still hold the lease. If we don't, the heartbeat task has
276	            // already set `lease_lost`; clean up the temp and bail
277	            // without racing the new owner.
278	            if lease_lost.is_cancelled() {
279	                warn!(
280	                    job_id = %job_id,
281	                    "Lease lost after write — discarding temp artifact without publishing"
282	                );
283	                best_effort_unlink(&temp_path, job_id).await;
284	                heartbeat_cancel.cancel();
285	                return;
286	            }
287	
288	            let has_sink = job.sink_config.is_some();
289	
290	            let prov_dv_id = _export_meta.dataset_version_id;
291	            let prov_dv = _export_meta.dataset_version;
292	            let prov_cs = _export_meta.completeness_status.as_deref();
293	            let prov_cc = _export_meta.completeness_coverage.as_ref();
294	            let prov_lri = _export_meta.last_ingestion_run_id;
295	
296	            let result_location = format!("exports/{}.{}", job_id, ext);
297	
298	            if has_sink {
299	                // Transition to 'delivering'. update_or_abort only
300	                // writes the row if we still own the lease (Ok(true)).
301	                // If Ok(false) ("someone else took over"), we clean up
302	                // our temp and exit without publishing.
303	                match update_or_abort(
304	                    repo,
305	                    job_id,
306	                    "delivering",
307	                    Some(record_count as i32),
308	                    Some(&result_location),
309	                    None,
310	                    worker_id,
311	                    None,
312	                    prov_dv_id,
313	                    prov_dv,
314	                    prov_cs,
315	                    prov_cc,
316	                    prov_lri,
317	                )
318	                .await
319	                {
320	                    Ok(()) => {}
321	                    Err(()) => {
322	                        best_effort_unlink(&temp_path, job_id).await;
323	                        heartbeat_cancel.cancel();
324	                        return;
325	                    }
326	                }
327	
328	                // Publish: atomic rename temp -> final. Only after the
329	                // lease-confirming 'delivering' update above, so a
330	                // stale worker never publishes over the new owner's
331	                // artifact. rename is atomic within the same
332	                // filesystem; the exports_dir is a single dir so this
333	                // holds.
334	                if let Err(e) = tokio::fs::rename(&temp_path, &final_path).await {
335	                    let err_msg = format!("Failed to publish export artifact: {e}");
336	                    error!(job_id = %job_id, error = %err_msg, "Export job failed");
337	                    best_effort_unlink(&temp_path, job_id).await;
338	                    let _ = update_or_abort(
339	                        repo,
340	                        job_id,
341	                        "failed",
342	                        Some(record_count as i32),
343	                        Some(&result_location),
344	                        Some(&err_msg),
345	                        worker_id,
346	                        None,
347	                        prov_dv_id,
348	                        prov_dv,
349	                        prov_cs,
350	                        prov_cc,
351	                        prov_lri,
352	                    )
353	                    .await;
354	                    heartbeat_cancel.cancel();
355	                    return;
356	                }
357	
358	                // Deliver to the sink from the already-streamed file.
359	                // `deliver_from_file` avoids loading the full artifact
