365	                {
366	                    Ok(sink_config) => match build_sink(&sink_config, export_dir) {
367	                        Ok(sink) => {
368	                            let delivery_meta = DeliveryMetadata {
369	                                job_id,
370	                                dataset: job.dataset.clone(),
371	                                format: job.format.clone(),
372	                                record_count,
373	                                dataset_version_id: _export_meta.dataset_version_id,
374	                                completeness_status: _export_meta.completeness_status.clone(),
375	                            };
376	                            match sink
377	                                .deliver_from_file(
378	                                    std::path::Path::new(&final_path),
379	                                    &delivery_meta,
380	                                )
381	                                .await
382	                            {
383	                                Ok(receipt) => Ok(receipt.destination),
384	                                Err(e) => {
385	                                    warn!(job_id = %job_id, error = %e, "Sink delivery failed");
386	                                    Err(format!(
387	                                        "Exported {} records, but sink delivery failed: {e}",
388	                                        record_count
389	                                    ))
390	                                }
391	                            }
392	                        }
393	                        Err(e) => {
394	                            warn!(job_id = %job_id, error = %e, "Failed to build sink");
395	                            Err(format!(
396	                                "Exported {} records, but sink build failed: {e}",
397	                                record_count
398	                            ))
399	                        }
400	                    },
401	                    Err(e) => {
402	                        warn!(job_id = %job_id, error = %e, "Failed to parse sink config");
403	                        Err(format!(
404	                            "Exported {} records, but sink config parse failed: {e}",
405	                            record_count
406	                        ))
407	                    }
408	                };
409	
410	                match delivery_result {
411	                    Ok(destination) => {
412	                        info!(
413	                            job_id = %job_id,
414	                            record_count,
415	                            destination = %destination,
416	                            "Export job completed with sink delivery"
417	                        );
418	                        let _ = update_or_abort(
419	                            repo,
420	                            job_id,
421	                            "completed",
422	                            Some(record_count as i32),
423	                            Some(&result_location),
424	                            None,
425	                            worker_id,
426	                            Some(&destination),
427	                            prov_dv_id,
428	                            prov_dv,
429	                            prov_cs,
430	                            prov_cc,
431	                            prov_lri,
432	                        )
