436	                        error!(job_id = %job_id, error = %err_msg, "Sink delivery failed");
437	                        let _ = update_or_abort(
438	                            repo,
439	                            job_id,
440	                            "failed",
441	                            Some(record_count as i32),
442	                            Some(&result_location),
443	                            Some(&err_msg),
444	                            worker_id,
445	                            None,
446	                            prov_dv_id,
447	                            prov_dv,
448	                            prov_cs,
449	                            prov_cc,
