464	                // mirrors the pre-publish lease check above.
465	                if let Err(e) = tokio::fs::rename(&temp_path, &final_path).await {
466	                    let err_msg = format!("Failed to publish export artifact: {e}");
467	                    error!(job_id = %job_id, error = %err_msg, "Export job failed");
468	                    best_effort_unlink(&temp_path, job_id).await;
469	                    let _ = update_or_abort(
470	                        repo,
471	                        job_id,
472	                        "failed",
473	                        None,
474	                        None,
475	                        Some(&err_msg),
476	                        worker_id,
477	                        None,
478	                        None,
479	                        None,
480	                        None,
481	                        None,
482	                        None,
483	                    )
484	                    .await;
485	                    heartbeat_cancel.cancel();
486	                    return;
487	                }
488	
489	                info!(
490	                    job_id = %job_id,
491	                    record_count,
492	                    result_location = %result_location,
493	                    "Export job completed"
494	                );
495	                match update_or_abort(
496	                    repo,
497	                    job_id,
498	                    "completed",
499	                    Some(record_count as i32),
500	                    Some(&result_location),
501	                    None,
502	                    worker_id,
503	                    None,
504	                    prov_dv_id,
505	                    prov_dv,
506	                    prov_cs,
507	                    prov_cc,
508	                    prov_lri,
509	                )
510	                .await
511	                {
512	                    Ok(()) => {}
513	                    Err(()) => {
514	                        // Lease was taken between rename and update. Pull
515	                        // the published artifact back so the new owner
516	                        // does not see our output.
517	                        warn!(
518	                            job_id = %job_id,
519	                            "Lease lost at final update — unpublishing artifact"
520	                        );
521	                        best_effort_unlink(&final_path, job_id).await;
522	                    }
523	                }
524	            }
525	        }
526	        Err(e) => {
527	            let err_msg = format!("Export failed: {e}");
528	            error!(job_id = %job_id, error = %err_msg, "Export job failed");
529	            // Attempt-scoped temp path: nothing was ever published at
530	            // final_path, so we only need to remove our temp.
531	            best_effort_unlink(&temp_path, job_id).await;
532	            let _ = update_or_abort(
533	                repo,
534	                job_id,
535	                "failed",
536	                None,
537	                None,
538	                Some(&err_msg),
539	                worker_id,
540	                None,
541	                None,
542	                None,
543	                None,
544	                None,
545	                None,
546	            )
547	            .await;
548	        }
549	    }
550	
551	    // Stop heartbeat after all writes and status updates are done.
552	    heartbeat_cancel.cancel();
553	}
