1	//! Durable export worker loop.
2	//!
3	//! Claims pending `export_jobs` rows from Postgres, streams the export
4	//! to disk via [`crate::export_stream::write_export_to_file`], optionally
5	//! delivers to a configured sink, and marks jobs complete/failed
6	//! durably. Heartbeats while running so that dead workers are detected
7	//! and their jobs reclaimed.
8	//!
9	//! Lease safety (PR #238 [P1] fix):
10	//!
11	//! The worker writes the export artifact to an *attempt-scoped* temp
12	//! file named `{job_id}.{worker_hash}.{ext}.tmp`, and only atomically
13	//! renames it to the canonical `{job_id}.{ext}` download path after a
14	//! lease-holder-confirming `update_export_job_status(..., worker_id)`
15	//! has returned `Ok(true)`. If the heartbeat loop reports the job's
16	//! lease was reclaimed, a `lease_lost` [`CancellationToken`] is
17	//! cancelled — that token is propagated into the page loop in
18	//! `write_export_to_file`, so the stale worker short-circuits the DB
19	//! snapshot, skips the rename, and removes its temp file. The new
20	//! owner starts from a clean state and writes to a distinct temp path,
21	//! so the two workers cannot truncate each other's artifacts or hand
22	//! out partial bytes via `/download`.
23	
24	use std::sync::Arc;
25	use std::time::Duration;
26	
27	use spectraplex_adapters::repo::Repository;
28	use spectraplex_core::config::AppConfig;
29	use spectraplex_core::materializer::{DeliveryMetadata, ExportFormat, SinkConfig};
30	use spectraplex_core::v2::ExportJob;
31	use tokio::sync::Semaphore;
32	use tokio_util::sync::CancellationToken;
33	use tracing::{error, info, warn};
34	use uuid::Uuid;
35	
36	use crate::build_sink;
37	use crate::export_stream::write_export_to_file;
38	
39	/// How often the worker polls for new jobs when idle.
40	const POLL_INTERVAL: Duration = Duration::from_secs(2);
41	
42	/// How often the worker sends heartbeats while executing a job.
43	const HEARTBEAT_INTERVAL: Duration = Duration::from_secs(30);
44	
45	/// Spawn the export worker loop. Returns immediately; the worker runs
46	/// until `cancel` is triggered.
47	pub fn spawn_export_worker(
48	    repo: Repository,
49	    config: AppConfig,
50	    job_semaphore: Arc<Semaphore>,
51	    cancel: CancellationToken,
52	) {
53	    let worker_id = format!("export-worker-{}", Uuid::new_v4());
54	    info!(worker_id = %worker_id, "Starting export worker");
55	
56	    tokio::spawn(async move {
57	        loop {
58	            tokio::select! {
59	                _ = cancel.cancelled() => {
60	                    info!(worker_id = %worker_id, "Export worker shutting down");
61	                    return;
62	                }
63	                _ = worker_tick(&repo, &config, &job_semaphore, &worker_id) => {}
64	            }
65	        }
66	    });
67	}
68	
69	async fn worker_tick(
70	    repo: &Repository,
71	    config: &AppConfig,
72	    job_semaphore: &Arc<Semaphore>,
73	    worker_id: &str,
74	) {
75	    let permit = match Arc::clone(job_semaphore).try_acquire_owned() {
76	        Ok(permit) => permit,
77	        Err(_) => {
78	            tokio::time::sleep(POLL_INTERVAL).await;
79	            return;
80	        }
81	    };
82	
83	    match repo.claim_export_job(worker_id).await {
84	        Ok(Some(job)) => {
85	            info!(
86	                job_id = %job.id,
87	                dataset = %job.dataset,
88	                format = %job.format,
89	                worker_id = %worker_id,
90	                "Claimed export job"
91	            );
92	            execute_export_job(repo, config, worker_id, &job, permit).await;
93	        }
94	        Ok(None) => {
95	            drop(permit);
96	            tokio::time::sleep(POLL_INTERVAL).await;
97	        }
98	        Err(e) => {
99	            drop(permit);
100	            error!(error = %e, worker_id = %worker_id, "Failed to claim export job");
101	            tokio::time::sleep(POLL_INTERVAL).await;
102	        }
103	    }
104	}
105	
106	/// Build an attempt-scoped temp path for this worker's export. Two
107	/// workers that race on the same `job_id` get different temp paths, so
108	/// a stale worker cannot truncate the new owner's artifact.
109	fn attempt_temp_path(exports_dir: &str, job_id: Uuid, worker_id: &str, ext: &str) -> String {
110	    // Short, filesystem-safe tag derived from the worker id. FNV-style
111	    // hash is fine — collision risk is negligible at the (active worker
112	    // count) scale this operates at.
113	    use std::collections::hash_map::DefaultHasher;
114	    use std::hash::{Hash, Hasher};
115	    let mut h = DefaultHasher::new();
116	    worker_id.hash(&mut h);
117	    let tag = format!("{:016x}", h.finish());
118	    format!("{exports_dir}/{job_id}.{tag}.{ext}.tmp")
119	}
120	
121	/// Best-effort remove a file, swallowing NotFound and logging other
122	/// errors. Used by the failure paths in `execute_export_job` to clean
123	/// up attempt-scoped temp artifacts without masking the real error.
124	async fn best_effort_unlink(path: &str, job_id: Uuid) {
125	    match tokio::fs::remove_file(path).await {
126	        Ok(()) => {}
127	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
128	        Err(e) => {
129	            warn!(
130	                job_id = %job_id,
131	                error = %e,
132	                file = %path,
133	                "Failed to clean up temp export artifact",
134	            );
135	        }
136	    }
137	}
138	
139	async fn execute_export_job(
140	    repo: &Repository,
141	    config: &AppConfig,
