157	    let lease_lost = CancellationToken::new();
158	    {
159	        let hb_repo = repo.clone();
160	        let hb_worker = worker_id.to_string();
161	        let hb_cancel = heartbeat_cancel.clone();
162	        let hb_lost = lease_lost.clone();
163	        let hb_job_id = job_id;
164	        tokio::spawn(async move {
