1	//! Gold-tier Hyperliquid analytics materialization and aggregation.
2	//!
3	//! Computes Gold datasets (hl_pnl_summary, hl_trade_history) from Silver
4	//! Hyperliquid data (hl_fills, hl_funding), and builds dashboard-ready
5	//! analytics responses (TraderAnalytics, MarketAnalytics).
6	
7	use bigdecimal::BigDecimal;
8	use spectraplex_core::materializer::{
9	    CoinMarketSummary, CoinPnlSummary, HlFillRecord, HlFundingPayment, HlPnlSummary,
10	    HlTradeHistory, MarketAnalytics, TraderAnalytics,
11	};
12	use std::collections::{HashMap, HashSet};
13	use uuid::Uuid;
14	
15	/// Compute PnL summary records from fills and funding payments.
16	///
17	/// Groups fills by (wallet_address, coin) — aggregating closed_pnl, fees,
18	/// and fill count — then merges funding totals for the same keys. Returns
19	/// one `HlPnlSummary` per (wallet, coin) pair.
20	pub fn compute_pnl_summary(
21	    wallet: &str,
22	    network: &str,
23	    fills: &[HlFillRecord],
24	    funding: &[HlFundingPayment],
25	    period_start: i64,
26	    period_end: i64,
27	) -> Vec<HlPnlSummary> {
28	    struct CoinAgg {
29	        total_closed_pnl: BigDecimal,
30	        total_fees: BigDecimal,
31	        total_funding: BigDecimal,
32	        fill_count: i64,
33	        trade_sizes: Vec<BigDecimal>,
34	        win_count: i64,
35	        loss_count: i64,
36	    }
37	
38	    let mut map: HashMap<String, CoinAgg> = HashMap::new();
39	
40	    for fill in fills {
41	        let agg = map.entry(fill.coin.clone()).or_insert_with(|| CoinAgg {
42	            total_closed_pnl: BigDecimal::from(0),
43	            total_fees: BigDecimal::from(0),
44	            total_funding: BigDecimal::from(0),
45	            fill_count: 0,
46	            trade_sizes: Vec::new(),
47	            win_count: 0,
48	            loss_count: 0,
49	        });
50	        agg.fill_count += 1;
51	        if let Some(ref cpnl) = fill.closed_pnl {
52	            agg.total_closed_pnl += cpnl;
53	            if cpnl > &BigDecimal::from(0) {
54	                agg.win_count += 1;
55	            } else if cpnl < &BigDecimal::from(0) {
56	                agg.loss_count += 1;
57	            }
58	        }
59	        if let Some(ref fee) = fill.fee {
60	            agg.total_fees += fee;
61	        }
62	        agg.trade_sizes.push(fill.size.clone());
63	    }
64	
65	    for fp in funding {
66	        let agg = map.entry(fp.coin.clone()).or_insert_with(|| CoinAgg {
67	            total_closed_pnl: BigDecimal::from(0),
68	            total_fees: BigDecimal::from(0),
69	            total_funding: BigDecimal::from(0),
70	            fill_count: 0,
71	            trade_sizes: Vec::new(),
72	            win_count: 0,
